// --- Java: Spring Cloud LoadBalancer ---
@LoadBalanced // This single annotation injects a client-side LB interceptor
@Bean
public RestTemplate restTemplate() {
    return new RestTemplate();
}
// Usage: URL is the service name, not an IP. Client picks the real IP locally.
restTemplate.getForObject("http://ORDER-SERVICE/orders/1", String.class);

# --- Python: gRPC Client-Side Round Robin ---
# gRPC natively supports client-side load balancing via DNS or custom resolvers
import grpc
# Connect to a headless service (DNS returns multiple A records)
channel = grpc.insecure_channel(
    'dns:///my-service:50051',
    options=[('grpc.lb_policy_name', 'round_robin')] # Built-in LB policy
)
